// Deterministic statistical tests (no LLM math)
// Pure-JS implementations — good enough for small samples typical in Ads reporting

const input = $input.first().json;
const testType = input.test_type;
const data = input.data || input;

function erf(x) {
  const sign = x < 0 ? -1 : 1;
  x = Math.abs(x);
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741;
  const a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const t = 1.0 / (1.0 + p * x);
  const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return sign * y;
}
function pnorm(z) { return 0.5 * (1 + erf(z / Math.sqrt(2))); }
function twoSidedP(z) { return 2 * (1 - pnorm(Math.abs(z))); }

function twoProportionZ(aSucc, aN, bSucc, bN) {
  const p1 = aSucc / aN, p2 = bSucc / bN;
  const pPool = (aSucc + bSucc) / (aN + bN);
  const se = Math.sqrt(pPool * (1 - pPool) * (1/aN + 1/bN));
  const z = (p1 - p2) / se;
  const p_value = twoSidedP(z);
  const diff = p1 - p2;
  const seDiff = Math.sqrt(p1*(1-p1)/aN + p2*(1-p2)/bN);
  const ci_95 = [diff - 1.96 * seDiff, diff + 1.96 * seDiff];
  return { p_value, ci_95, effect_size: diff, test_stat: z, n_a: aN, n_b: bN };
}

function welchT(a, b) {
  const mean = arr => arr.reduce((s, x) => s + x, 0) / arr.length;
  const variance = arr => { const m = mean(arr); return arr.reduce((s, x) => s + (x - m) ** 2, 0) / (arr.length - 1); };
  const m1 = mean(a), m2 = mean(b), v1 = variance(a), v2 = variance(b), n1 = a.length, n2 = b.length;
  const se = Math.sqrt(v1 / n1 + v2 / n2);
  const t = (m1 - m2) / se;
  const df = (v1 / n1 + v2 / n2) ** 2 / ((v1 / n1) ** 2 / (n1 - 1) + (v2 / n2) ** 2 / (n2 - 1));
  const p_value = twoSidedP(t);
  return { p_value, ci_95: [(m1 - m2) - 1.96 * se, (m1 - m2) + 1.96 * se], effect_size: m1 - m2, test_stat: t, df };
}

function cochranArmitage(counts, totals, scores) {
  const n = totals.reduce((s, x) => s + x, 0);
  const r = counts.reduce((s, x) => s + x, 0);
  const p = r / n;
  let num = 0, denom = 0;
  for (let i = 0; i < counts.length; i++) {
    num += scores[i] * (counts[i] - totals[i] * p);
    denom += scores[i] * scores[i] * totals[i];
  }
  const variance = p * (1 - p) * (denom - n * Math.pow(scores.reduce((s, x, i) => s + x * totals[i], 0) / n, 2));
  const z = num / Math.sqrt(variance);
  return { p_value: twoSidedP(z), test_stat: z, effect_size: num };
}

function bayesianBetaBinomial(aSucc, aN, bSucc, bN, alpha=1, beta=1) {
  // P(p_a > p_b) via Monte Carlo (simple approximation)
  const samples = 10000;
  let aWins = 0;
  for (let i = 0; i < samples; i++) {
    // Beta sample via gamma approx — very rough; for production use a proper lib
    const pa = (aSucc + alpha) / (aN + alpha + beta);
    const pb = (bSucc + alpha) / (bN + alpha + beta);
    // noise term
    const jitterA = (Math.random() - 0.5) * Math.sqrt(pa * (1-pa) / (aN + alpha + beta));
    const jitterB = (Math.random() - 0.5) * Math.sqrt(pb * (1-pb) / (bN + alpha + beta));
    if (pa + jitterA > pb + jitterB) aWins++;
  }
  const prob = aWins / samples;
  return { p_value: 1 - prob, posterior_prob_a_gt_b: prob, effect_size: aSucc / aN - bSucc / bN };
}

let result;
try {
  if (testType === 'two_proportion_z') {
    result = twoProportionZ(data.group_a.successes, data.group_a.n, data.group_b.successes, data.group_b.n);
  } else if (testType === 'welch_t') {
    result = welchT(data.samples_a, data.samples_b);
  } else if (testType === 'cochran_armitage') {
    result = cochranArmitage(data.counts, data.totals, data.scores || data.counts.map((_, i) => i));
  } else if (testType === 'bayesian_beta_binomial') {
    result = bayesianBetaBinomial(data.group_a.successes, data.group_a.n, data.group_b.successes, data.group_b.n);
  } else {
    result = { error: 'Unknown test_type: ' + testType };
  }
  result.test_type = testType;
  result.verdict_suggestion = result.p_value < 0.05 ? 'significant' : (result.p_value < 0.1 ? 'trend_only' : 'not_significant');
} catch (e) {
  result = { error: e.message, test_type: testType };
}

return [{ json: result }];
